import unittest
from route_parts import *
class RouteParts(unittest.TestCase):
    def test_separators_and_limit(self):
        for text,limit,expected in [('depot:oak/leaf',0,['depot',':','oak','/','leaf']),('/oak:',0,['','/','oak',':','']),('oak::/leaf',0,['oak','::/','leaf']),('oak:pine/elm',1,['oak',':','pine/elm']),('oak:pine/elm',2,['oak',':','pine','/','elm']),('oak',0,['oak']),('',0,['']),('::',0,['','::',''])]:
            with self.subTest(text=text,limit=limit):
                self.assertEqual(split_route(text,limit),expected)

